func IdToUri(id string) string {
	normalized := strings.ReplaceAll(id, "\uFE0E", "")
	normalized = strings.ReplaceAll(normalized, "\uFE0F", "")
	normalized = strings.TrimSpace(normalized)
	if normalized == "" {
