	if hasPrefix(normalized, EmojiGoal) { return "goal" }
	if hasPrefix(normalized, EmojiDrafts) { return "drafts" }
	if hasPrefix(normalized, EmojiDraft) { return "draft" }
	if hasPrefix(normalized, EmojiTodos) { return "todos" }
	if hasPrefix(normalized, EmojiTodo) { return "todo" }
	if hasPrefix(normalized, EmojiPolicies) { return "policies" }
	if hasPrefix(normalized, EmojiPolicy) { return "policy" }
